insert into public.admin_help_items(help_key,title_fa,body_fa,title_en,body_en,warning_fa,warning_en) values
('theme.switch','تعویض قالب','انتخاب قالب فقط Draft را تغییر می‌دهد تا بتوانید قبل از انتشار ظاهر جدید را بررسی کنید. محتوای سایت از قالب جداست و حذف نمی‌شود.','Switch theme','Selecting a theme changes the draft presentation only. Site content is separate from the theme and is not deleted.','قالب Deprecated را فقط برای سازگاری قدیمی نگه دارید و برای سایت جدید انتخاب نکنید.','Keep deprecated themes only for legacy compatibility and avoid selecting them for new sites.'),
('theme.publish','انتشار قالب','Publish تنظیمات Draft را به نسخه عمومی سایت تبدیل می‌کند و نسخه قبلی در Theme Revision نگهداری می‌شود.','Publish theme','Publish promotes draft settings to the public website and keeps the previous state in Theme Revisions.','قبل از انتشار تغییرات بزرگ، Preview را بررسی کنید.','Review Preview before publishing large visual changes.'),
('theme.admin_skin','هماهنگی پنل مدیریت','اگر فعال باشد، پنل مدیریت Accent و برخی عناصر بصری را از هویت برند می‌گیرد ولی رنگ‌های امنیت، خطا، موفقیت و هشدار استاندارد باقی می‌مانند.','Admin skin sync','When enabled, admin accents inherit the brand identity while security, error, success and warning semantics remain standardized.',null,null)
